import{_ as I,o as i,c as e,a0 as a}from"./chunks/framework.DQOulFGV.js";const l="data:image/svg+xml;base64,",d="data:image/svg+xml;base64,",r=JSON.parse('{"title":"第1章 缓存穿透","description":"","frontmatter":{},"headers":[],"relativePath":"redis/03-cache-engineering/chapter-01-penetration.md","filePath":"redis/03-cache-engineering/chapter-01-penetration.md"}'),g={name:"redis/03-cache-engineering/chapter-01-penetration.md"};function s(m,t,n,Z,h,c){return i(),e("div",null,[...t[0]||(t[0]=[a('<h1 id="第1章-缓存穿透" tabindex="-1">第1章 缓存穿透 <a class="header-anchor" href="#第1章-缓存穿透" aria-label="Permalink to &quot;第1章 缓存穿透&quot;">​</a></h1><blockquote><p>缓存穿透指查询一个「缓存和数据库都不存在」的数据。这类请求每次都穿透缓存直达数据库，当被恶意或异常地大量发起时，会把数据库打垮。本章讲解穿透的成因与两种主流解法。</p></blockquote><hr><h2 id="_1-1-问题" tabindex="-1">1.1 问题 <a class="header-anchor" href="#_1-1-问题" aria-label="Permalink to &quot;1.1 问题&quot;">​</a></h2><p>正常查询会先查缓存，命中直接返回；未命中则查数据库，再把结果写入缓存。</p><p><img src="'+l+`" alt="缓存穿透问题流程"></p><p>穿透的根源在于「缓存和数据库都没有数据」：既然数据库查不到，就不会写缓存，于是下一次相同请求还是查不到缓存、还是直达数据库。</p><p>典型场景：</p><table tabindex="0"><thead><tr><th style="text-align:left;">场景</th><th style="text-align:left;">说明</th></tr></thead><tbody><tr><td style="text-align:left;">恶意攻击</td><td style="text-align:left;">批量请求大量不存在的 key</td></tr><tr><td style="text-align:left;">业务漏洞</td><td style="text-align:left;">用自增 ID 猜测，查询不存在的数据</td></tr><tr><td style="text-align:left;">数据冷启动</td><td style="text-align:left;">大量新业务 ID 尚未写入数据库</td></tr></tbody></table><p>危害：数据库反复执行无效查询，连接被占满，最终拖垮整个系统。</p><hr><h2 id="_1-2-布隆过滤器" tabindex="-1">1.2 布隆过滤器 <a class="header-anchor" href="#_1-2-布隆过滤器" aria-label="Permalink to &quot;1.2 布隆过滤器&quot;">​</a></h2><p>布隆过滤器（Bloom Filter）用于「快速判断一个 key 是否可能存在」——查询前先过滤掉必然不存在的 key。</p><h3 id="原理" tabindex="-1">原理 <a class="header-anchor" href="#原理" aria-label="Permalink to &quot;原理&quot;">​</a></h3><p>布隆过滤器是一个位数组 + 多个哈希函数：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>插入元素 x：</span></span>
<span class="line"><span>  用 k 个哈希函数对 x 求值，得到 k 个位置，把这 k 个位置都置为 1</span></span>
<span class="line"><span></span></span>
<span class="line"><span>查询元素 y：</span></span>
<span class="line"><span>  同样求 k 个位置，若所有位置都是 1，则「可能存在」</span></span>
<span class="line"><span>  若任意一个位置是 0，则「必然不存在」</span></span></code></pre></div><h3 id="特性" tabindex="-1">特性 <a class="header-anchor" href="#特性" aria-label="Permalink to &quot;特性&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">特性</th><th style="text-align:left;">说明</th></tr></thead><tbody><tr><td style="text-align:left;">空间高效</td><td style="text-align:left;">固定大小的位数组，不存元素本身</td></tr><tr><td style="text-align:left;">必然不存在</td><td style="text-align:left;">判「不存在」100% 准确</td></tr><tr><td style="text-align:left;">可能误判</td><td style="text-align:left;">判「存在」有误判率（把不存在误判为存在）</td></tr><tr><td style="text-align:left;">不可删除</td><td style="text-align:left;">传统布隆过滤器不支持删除元素</td></tr></tbody></table><h3 id="用法" tabindex="-1">用法 <a class="header-anchor" href="#用法" aria-label="Permalink to &quot;用法&quot;">​</a></h3><p>在查缓存前先过布隆过滤器：</p><p><img src="`+d+'" alt="布隆过滤器拦截流程"></p><p>布隆过滤器拦截了大部分「不存在」的请求，只有少数「可能存在的误判」会继续查缓存和数据库。</p><p>Redis 通过 RedisBloom 模块提供布隆过滤器，Java 也可用 Guava、Redisson 内置实现。</p><hr><h2 id="_1-3-缓存空值" tabindex="-1">1.3 缓存空值 <a class="header-anchor" href="#_1-3-缓存空值" aria-label="Permalink to &quot;1.3 缓存空值&quot;">​</a></h2><p>缓存空值指「把不存在的查询结果（空值）也写入缓存」——这样下一次相同请求就能命中缓存，不再穿透。</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">SET</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cache:user:9999</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> EX</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 60</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # 不存在的 key 缓存空字符串，60 秒过期</span></span></code></pre></div><p>要点：</p><table tabindex="0"><thead><tr><th style="text-align:left;">要点</th><th style="text-align:left;">说明</th></tr></thead><tbody><tr><td style="text-align:left;">空值也缓存</td><td style="text-align:left;">查不到也写一个空值进缓存</td></tr><tr><td style="text-align:left;">设置短 TTL</td><td style="text-align:left;">空值缓存时间要短（如 60 秒），避免长期占用</td></tr><tr><td style="text-align:left;">数据不一致风险</td><td style="text-align:left;">数据可能之后被写入，但空值缓存还没过期</td></tr></tbody></table><p>缓存空值实现简单，但会引入「缓存与数据库短暂不一致」的问题：某个 key 刚被判定不存在、缓存了空值，随后数据被写入，但空值缓存未过期，导致短暂返回空。</p><hr><h2 id="_1-4-方案对比" tabindex="-1">1.4 方案对比 <a class="header-anchor" href="#_1-4-方案对比" aria-label="Permalink to &quot;1.4 方案对比&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">维度</th><th style="text-align:left;">布隆过滤器</th><th style="text-align:left;">缓存空值</th></tr></thead><tbody><tr><td style="text-align:left;">实现复杂度</td><td style="text-align:left;">较高（需引入模块/客户端）</td><td style="text-align:left;">低（几行代码）</td></tr><tr><td style="text-align:left;">内存占用</td><td style="text-align:left;">固定，与 key 数量无关</td><td style="text-align:left;">与空值 key 数量成正比</td></tr><tr><td style="text-align:left;">误判</td><td style="text-align:left;">有（不存在误判为存在）</td><td style="text-align:left;">无</td></tr><tr><td style="text-align:left;">数据一致性</td><td style="text-align:left;">好（不缓存数据本身）</td><td style="text-align:left;">可能短暂不一致</td></tr><tr><td style="text-align:left;">适用场景</td><td style="text-align:left;">大规模、key 空间巨大</td><td style="text-align:left;">小规模、简单场景</td></tr></tbody></table><p>选型建议：key 空间大、追求极致防护用布隆过滤器；场景简单、快速上线用缓存空值。两者也可结合使用。</p>',34)])])}const y=I(g,[["render",s]]);export{r as __pageData,y as default};
